import styles from "./2d.module.css";

function App() {
  const [isPlaced, setIsPlaced] = useState(false);

  const togglePlacementStatus = () => {
    setIsPlaced(!isPlaced);
  };

  return (
    <div className={styles["container"]}>
      <h1>Campus Placement Dashboard</h1>

      {isPlaced ? (
        <div className={`${styles["status-card"]} ${styles.success}`}>
          <h2>🎉 Congratulations!</h2>
          <p>You have been placed successfully.</p>
        </div>
      ) : (
        <div className={`${styles["status-card"]} ${styles.pending}`}>
          <h2>⏳ Placement Pending</h2>
          <p>Keep preparing and applying for opportunities.</p>
        </div>
      )}

      <button onClick={togglePlacementStatus}>Toggle Placement Status</button>
    </div>
  );
}

export default App;

