import { useEffect, useState } from "react";
import "./3b.css";

function Experiment3b() {
  const [students, setStudents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const fetchStudents = async () => {
      try {
        const response = await fetch(
          "https://jsonplaceholder.typicode.com/users",
        );

        if (!response.ok) {
          throw new Error("Failed to fetch student data.");
        }

        const data = await response.json();

        setStudents(data);
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchStudents();
  }, []);

  return (
    <div className="experiment-container">
      <h1>Campus Placement Dashboard</h1>
      <h2>Student Candidates</h2>
      {loading && <p className="loading">Loading student data...</p>}
      {error && <p className="error">{error}</p>}
      {!loading && !error && (
        <div className="student-grid">
          {students.map((student) => (
            <div className="student-card" key={student.id}>
              <h3>{student.name}</h3>
              <p><strong>Email:</strong> {student.email}</p>
              <p><strong>Company:</strong> {student.company.name}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default Experiment3b;

