.experiment-container {
  min-height: 100vh;
  padding: 40px;
  background: #eef2f7;
  text-align: center;
  font-family: Arial, Helvetica, sans-serif;
}

.experiment-container h1 {
  color: #1565c0;
}

.experiment-container h2 {
  margin-bottom: 30px;
}

.loading {
  font-size: 18px;
  color: #555;
}

.error {
  color: #c62828;
  font-weight: bold;
}

.student-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
  max-width: 900px;
  margin: auto;
}

.student-card {
  background: white;
  padding: 20px;
