import { useState } from "react";
import "./3d.css";

function Experiment3d() {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    branch: "",
    cgpa: "",
    role: "",
    status: "",
  });

  const [submittedStudent, setSubmittedStudent] = useState(null);

  const handleChange = (event) => {
    const { name, value } = event.target;

    setFormData({
      ...formData,
      [name]: value,
    });
  };

  const handleSubmit = (event) => {
    event.preventDefault();

    setSubmittedStudent(formData);
  };

  return (
    <div className="form-container">
      <h1>Campus Placement Dashboard</h1>

      <div className="form-card">
        <h2>Student Placement Registration</h2>

        <form onSubmit={handleSubmit}>
          <label htmlFor="name">Student Name</label>

          <input
            type="text"
            id="name"
            name="name"
            value={formData.name}
            onChange={handleChange}
            placeholder="Enter your name"
            required
          />

          <label htmlFor="email">Email</label>

          <input
            type="email"
            id="email"
            name="email"
            value={formData.email}
            onChange={handleChange}
            placeholder="Enter your email"
            required
          />

          <label htmlFor="branch">Branch</label>

          <select
            id="branch"
            name="branch"
            value={formData.branch}
            onChange={handleChange}
            required
          >
            <option value="">Select Branch</option>

            <option value="CSE">Computer Science and Engineering</option>

            <option value="ECE">
              Electronics and Communication Engineering
            </option>

            <option value="EEE">Electrical and Electronics Engineering</option>

            <option value="IT">Information Technology</option>
          </select>

          <label htmlFor="cgpa">CGPA</label>

          <input
            type="number"
            id="cgpa"
            name="cgpa"
            value={formData.cgpa}
            onChange={handleChange}
            placeholder="Enter CGPA"
            min="0"
            max="10"
            step="0.01"
            required
          />

          <label htmlFor="role">Preferred Job Role</label>

          <input
            type="text"
            id="role"
            name="role"
            value={formData.role}
            onChange={handleChange}
            placeholder="Example: Software Developer"
            required
          />

          <label htmlFor="status">Placement Status</label>

          <select
            id="status"
            name="status"
            value={formData.status}
            onChange={handleChange}
            required
          >
            <option value="">Select Status</option>

            <option value="Looking for opportunities">
              Looking for opportunities
            </option>

            <option value="Applied">Applied</option>

            <option value="Shortlisted">Shortlisted</option>
          </select>

          <button type="submit">Register for Placement</button>
        </form>
      </div>

      {submittedStudent && (
        <div className="result-card">
          <h2>Registration Successful</h2>

          <p>
            <strong>Name:</strong> {submittedStudent.name}
          </p>

          <p>
            <strong>Email:</strong> {submittedStudent.email}
          </p>

          <p>
            <strong>Branch:</strong> {submittedStudent.branch}
          </p>

          <p>
            <strong>CGPA:</strong> {submittedStudent.cgpa}
          </p>

          <p>
            <strong>Preferred Role:</strong> {submittedStudent.role}
          </p>

          <p>
            <strong>Status:</strong> {submittedStudent.status}
          </p>
        </div>
      )}
    </div>
  );
}

export default Experiment3d;

