import express from "express";

const app = express();
const PORT = 3000;

// Middleware to read JSON request bodies
app.use(express.json());

// Sample placement application data
let applications = [
  {
    id: 1,
    studentName: "Rahul",
    company: "TCS",
    position: "Software Engineer",
    status: "Applied",
  },
  {
    id: 2,
    studentName: "Priya",
    company: "Infosys",
    position: "System Engineer",
    status: "Shortlisted",
  },
];

let nextId = 3;

// Open the application list when visiting the server's home page.
app.get("/", (req, res) => res.redirect("/applications"));

// CREATE - Add a new application
app.post("/applications", (req, res) => {
  const { studentName, company, position, status = "Applied" } = req.body || {};
  if (
    ![studentName, company, position, status].every(
      (value) => typeof value === "string" && value.trim(),
    )
  ) {
    return res
      .status(400)
      .json({
        message: "Enter studentName, company, position and a valid status.",
      });
  }
  const newApplication = {
    id: nextId++,
    studentName: studentName.trim(),
    company: company.trim(),
    position: position.trim(),
    status: status.trim(),
  };

  applications.push(newApplication);

  res.status(201).json({
    message: "Application created successfully",
    application: newApplication,
  });
});

// READ - Get all applications
app.get("/applications", (req, res) => {
  res.json(applications);
});

// READ - Get a single application
app.get("/applications/:id", (req, res) => {
  const id = Number(req.params.id);
  if (!Number.isInteger(id) || id <= 0)
    return res
      .status(400)
      .json({ message: "Use a positive integer application ID." });

  const application = applications.find((application) => application.id === id);

  if (!application) {
    return res.status(404).json({
      message: "Application not found",
    });
  }

  res.json(application);
});

// UPDATE - Update an existing application
app.put("/applications/:id", (req, res) => {
  const id = Number(req.params.id);
  if (!Number.isInteger(id) || id <= 0)
    return res
      .status(400)
      .json({ message: "Use a positive integer application ID." });

  const application = applications.find((application) => application.id === id);

  if (!application) {
    return res.status(404).json({
      message: "Application not found",
    });
  }

  const { studentName, company, position, status = "Applied" } = req.body || {};
  if (
    ![studentName, company, position, status].every(
      (value) => typeof value === "string" && value.trim(),
    )
  ) {
    return res
      .status(400)
      .json({
        message: "Enter studentName, company, position and a valid status.",
      });
  }
  application.studentName = studentName.trim();
  application.company = company.trim();
  application.position = position.trim();
  application.status = status.trim();

  res.json({
    message: "Application updated successfully",
    application: application,
  });
});

// DELETE - Delete an application
app.delete("/applications/:id", (req, res) => {
  const id = Number(req.params.id);
  if (!Number.isInteger(id) || id <= 0)
    return res
      .status(400)
      .json({ message: "Use a positive integer application ID." });

  const index = applications.findIndex((application) => application.id === id);

  if (index === -1) {
    return res.status(404).json({
      message: "Application not found",
    });
  }

  const deletedApplication = applications.splice(index, 1);

  res.json({
    message: "Application deleted successfully",
    application: deletedApplication[0],
  });
});

app.use((error, req, res, next) => {
  if (res.headersSent) return next(error);
  res
    .status(error.status || 500)
    .json({
      message:
        error.status === 400
          ? "Send valid JSON in the request body."
          : "Unable to complete the request.",
    });
});

// Start the server
app.listen(PORT, () => {
  console.log(`CRUD server running at http://localhost:${PORT}`);
});

