import express from "express";
import db from "./db.js";

const app = express();
const PORT = 3000;

app.use(express.json());

// Test the database connection
app.get("/", async (req, res) => {
  try {
    const [rows] = await db.query("SELECT 1 AS connection_status");

    res.json({
      message: "Express API connected to MySQL successfully",
      databaseStatus: rows[0].connection_status,
    });
  } catch (error) {
    console.error("Database connection error:", error.message);

    res.status(500).json({
      message: "Database connection failed",
    });
  }
});

// READ: Retrieve all placement applications
app.get("/applications", async (req, res) => {
  try {
    const [rows] = await db.query("SELECT * FROM applications");

    res.json(rows);
  } catch (error) {
    console.error(error.message);

    res.status(500).json({
      message: "Failed to retrieve applications",
    });
  }
});

// CREATE: Insert a placement application
app.post("/applications", async (req, res) => {
  try {
    const { student_name, company, position, status } = req.body || {};

    if (
      ![student_name, company, position].every(
        (value) => typeof value === "string" && value.trim(),
      )
    ) {
      return res.status(400).json({
        message: "student_name, company and position are required",
      });
    }

    const [result] = await db.execute(
      `INSERT INTO applications
       (student_name, company, position, status)
       VALUES (?, ?, ?, ?)`,
      [student_name, company, position, status || "Applied"],
    );

    res.status(201).json({
      message: "Application inserted successfully",
      id: result.insertId,
    });
  } catch (error) {
    console.error(error.message);

    res.status(500).json({
      message: "Failed to insert application",
    });
  }
});

// Start the Express server
app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});

